\sum_{n \ge 1} x^n \sum_{\pi \in S_n(2413,3142)}t^{p(\pi)} = G(x,t).
\end{equation*}

\label{N15}
	We have
	$$
	\sum_{n \ge 1} x^n \sum_{\pi \in S_n(2413,3142)} t^{\,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.5]
			\foreach \x/\y in {}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
(\pi)} = F(xt) = \frac{1 - t x - \sqrt{\,1 - 6 t x + t^{2} x^{2}}}{2}.$$

\label{N16}
We have
	$$
	F(x,t) := \sum_{n \ge 1} x^n \sum_{\pi \in S_n(2413,3142)} 
	t^{\,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.5]
			\foreach \x/\y in {1/0,1/1,0/0,0/1}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
(\pi)}= \frac{1 + (2t-3 )\,x - \sqrt{\,1 - 6x + x^{2}}}{2}.
	$$

Clearly, the only separable permutation that contains the pattern  \hspace{-1mm}$										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,1/1,0/0,0/1}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
$ is $1$, so  
	\begin{equation}\label{N16-expr-A}
		F(x,t) = tx + F(x) - x .
	\end{equation}
	By substituting~\eqref{eq:separable-gf}~into~\eqref{N16-expr-A}, we obtain the desired result.

\label{N5}
	For $p\in\{\hspace{-1mm}										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {0/1,0/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

