	\end{tikzpicture}}
,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,1/1}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {0/1,1/1}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,0/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
\}$, we have
	$$
\begin{aligned}
	F(x,t):
	&= \sum_{n \ge 1} x^n \sum_{\pi \in S_n(2413,3142)}
	t^{p(\pi)}= \frac{t(1 - x - \sqrt{1 - 6x + x^{2}})}{2}.
\end{aligned}
    $$

W.l.o.g., consider N5=\hspace{-1mm}$										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {0/1,0/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
$. It occurs exactly once, as the leftmost element, in any separable permutation, so $F(x,t) = tF(x)$, and the result follows by~\eqref{eq:separable-gf}.

\label{N9}
	For $p\in\{\hspace{-1mm}										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,1/1,0/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,0/1,0/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {0/0,1/1,0/1}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
,										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,1/1,0/1}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
\}$, we have
	$$
	\begin{aligned}
		F(x,t):
		&= \sum_{n \ge 1} x^n \sum_{\pi \in S_n(2413,3142)}
		t^{p(\pi)}  \\[4pt]
		&= \frac{1}{2}\!\left(
		1 - x - \sqrt{1 - 6x + x^{2}}
		-(t-1)\,x\left(x-3 + \sqrt{1 - 6x + x^{2}}\right)
		\right).
	\end{aligned}
	$$

W.l.o.g., consider the pattern N9 $=\hspace{-1mm}										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,1/1,0/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
$. 
Only the element $1$ occurring at the end of a permutation can be an occurrence of the pattern 
\hspace{-1mm}$										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {1/0,1/1,0/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

			\draw (0.01,0.01) grid (1+0.99,1+0.99);
			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
$, and in this position, $1$ cannot be part of an occurrence 
of the patterns $2413$ or $3142$. Hence, if $A(x)$ denotes the g.f.\ for separable permutations that end with 
their smallest element, we have
\begin{equation}\label{N9-expr-A}
    F(x,t) = tA(x) + F(x) - A(x).
\end{equation}
Moreover, any permutation counted by $A(x)$ can be generated by taking any separable permutation or the empty 
permutation and adjoining the new smallest element to its right, so $A(x) = x\,(F(x)+1)$. Together with 
 \eqref{eq:separable-gf} and \eqref{N9-expr-A}, this gives the desired result.

\label{joint-separ-length-1}
		We have $\hspace{-1mm}										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
