	\end{tikzpicture}}
\sim_{jd}
 \hspace{-1mm}										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.6]
			\foreach \x/\y in {0/0,1/1}		\fill[gray!50] (\x,\y) rectangle +(1,1);

