			\foreach \x/\y in {1/1}		\filldraw (\x,\y) circle (6pt);
	\end{tikzpicture}}
$. Moreover, if
	$$
	F(x,t) := \sum_{n \ge 1} x^n \sum_{\pi \in S_n(2413,3142)} 
	t^{\hspace{-1mm}										              
	\raisebox{0.6ex}{
		\begin{tikzpicture}[scale=0.35, baseline=(current bounding box.center), scale = 0.5]
			\foreach \x/\y in {0/1,1/0}		\fill[gray!50] (\x,\y) rectangle +(1,1);

